def compressed_arms(devices):
    endpoints=sorted({p for x,length in devices for p in (x-length,x,x+length)})
    index={x:i for i,x in enumerate(endpoints)}
    weights=[b-a for a,b in zip(endpoints,endpoints[1:])]
    arms=[]
    for x,length in devices:
        l,m,r=index[x-length],index[x],index[x+length]
        arms.append((((1<<(m-l))-1)<<l,((1<<(r-m))-1)<<m))
    return weights,arms

def weight(mask,weights):
    total=0
    while mask:
        bit=mask&-mask; total+=weights[bit.bit_length()-1]; mask-=bit
    return total

def brute(devices):
    weights,arms=compressed_arms(devices)
    unions={0}
    for left,right in arms:
        unions={previous|arm for previous in unions for arm in (left,right)}
    return max(weight(mask,weights) for mask in unions),len(unions)

def encode(devices):
    return str(len(devices))+'\n'+''.join(str(x)+' '+str(length)+'\n' for x,length in devices)
